CREATE OR REPLACE FUNCTION public.qb_library_can_upload(p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO '' AS $$ select auth.uid() is not null and exists(select 1 from public.qb_image_library_config where enabled) and p_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}[.](png|jpg|jpeg|webp|gif|heic|heif|pdf)$' and not exists(select 1 from public.qb_image_library_items i where i.id::text=split_part(p_path,'/',1) and i.created_by is distinct from auth.uid()); $$;
